html:
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set student = frappe.get_doc("Student", doc.custom_student) if doc.custom_student else None -%}
{%- set so_name = doc.items[0].sales_order if doc.items and doc.items[0].sales_order else None -%}
{%- set so = frappe.get_doc("Sales Order", so_name) if so_name else None -%}
{%- set enr = frappe.get_doc("Student Batch Enrollment", so.student_batch_enrollment) if so and so.student_batch_enrollment else None -%}
{%- set pe_rows = frappe.get_all("Payment Entry Reference", filters={"reference_doctype": "Sales Invoice", "reference_name": doc.name, "docstatus": 1}, fields=["parent"]) -%}
{%- set pe = frappe.get_doc("Payment Entry", pe_rows[0].parent) if pe_rows else None -%}
{%- set ns = namespace(paid=0, pending=0) -%}
{%- if so -%}
  {%- for ps in so.payment_schedule -%}{%- set ns.paid = ns.paid + (ps.paid_amount or 0) -%}{%- endfor -%}
  {%- set ns.pending = (so.grand_total or 0) - ns.paid -%}
{%- endif -%}
{%- set paid_total = ns.paid -%}
{%- set pending_total = ns.pending -%}
<style>
  .rc{font-family:Inter,Arial,Helvetica,sans-serif;color:#111;font-size:12px;max-width:720px;margin:0 auto}
  .rc-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #1e3a8a;padding-bottom:10px;margin-bottom:14px}
  .rc-inst{font-size:20px;font-weight:700;color:#1e3a8a} .rc-sub{color:#555;font-size:11px;line-height:1.5}
  .rc-title{text-align:right} .rc-title h2{margin:0;font-size:18px;letter-spacing:.06em;color:#1e3a8a} .rc-title div{color:#444;margin-top:4px}
  .rc-grid{display:flex;gap:24px;margin:10px 0 14px} .rc-box{flex:1;border:1px solid #cbd5e1;border-radius:6px;padding:10px 12px}
  .rc-box h4{margin:0 0 6px;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#64748b}
  .rc-kv{display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px dashed #e2e8f0} .rc-kv:last-child{border-bottom:0} .rc-kv span:last-child{font-weight:600;text-align:right}
  table.rc-t{width:100%;border-collapse:collapse;margin:8px 0} .rc-t th{background:#dbeafe;color:#1e3a8a;text-align:left;padding:7px 9px;border:1px solid #bfdbfe} .rc-t td{padding:7px 9px;border:1px solid #cbd5e1} .rc-t .n{text-align:right;white-space:nowrap}
  .rc-amt{display:flex;justify-content:flex-end;margin-top:6px} .rc-amt table td{padding:5px 12px} .rc-amt .g td{font-size:15px;font-weight:700;border-top:2px solid #1e3a8a}
  .rc-words{margin:8px 0 14px;font-style:italic;color:#333}
  .rc-bal{background:#fff7ed;border:1px solid #fed7aa;border-radius:6px;padding:8px 12px;display:flex;justify-content:space-between;margin-top:8px}
  .rc-bal b.red{color:#b91c1c} .rc-bal b.green{color:#166534}
  .rc-foot{display:flex;justify-content:space-between;margin-top:36px;font-size:11px;color:#444} .rc-sign{text-align:center;width:220px;border-top:1px solid #333;padding-top:4px}
  .rc-note{font-size:10px;color:#777;margin-top:14px;text-align:center}
  .rc-cancel{position:absolute;left:50%;top:40%;transform:translate(-50%,-50%) rotate(-25deg);font-size:64px;color:rgba(185,28,28,.18);font-weight:800;letter-spacing:.2em}
</style>
<div class="rc">
  {% if doc.docstatus == 2 %}<div class="rc-cancel">CANCELLED</div>{% endif %}
  <div class="rc-head">
    <div>
      <div class="rc-inst">{{ company.company_name }}</div>
      <div class="rc-sub">{{ frappe.db.get_value("Address", frappe.get_all("Dynamic Link", filters={"link_doctype":"Company","link_name":doc.company,"parenttype":"Address"}, pluck="parent")[0], "address_line1") if frappe.get_all("Dynamic Link", filters={"link_doctype":"Company","link_name":doc.company,"parenttype":"Address"}, pluck="parent") else "" }}
        {% if company.gstin %}<br>GSTIN {{ company.gstin }}{% endif %}{% if company.phone_no %} · {{ company.phone_no }}{% endif %}{% if company.email %} · {{ company.email }}{% endif %}</div>
    </div>
    <div class="rc-title"><h2>FEE RECEIPT</h2>
      <div><b>{{ doc.name }}</b><br>{{ frappe.utils.formatdate(doc.posting_date) }}</div></div>
  </div>

  <div class="rc-grid">
    <div class="rc-box"><h4>Received from</h4>
      <div class="rc-kv"><span>Student</span><span>{{ student.student_name if student else doc.customer_name }}</span></div>
      {% if student %}<div class="rc-kv"><span>Student ID</span><span>{{ student.name }}</span></div>
      <div class="rc-kv"><span>Mobile</span><span>{{ student.mobile or "" }}</span></div>{% endif %}
    </div>
    <div class="rc-box"><h4>Towards</h4>
      {% if enr %}<div class="rc-kv"><span>Course</span><span>{{ enr.course_name }}</span></div>
      <div class="rc-kv"><span>Batch</span><span>{{ enr.batch }}</span></div>{% endif %}
      {% if pe %}<div class="rc-kv"><span>Mode</span><span>{{ pe.mode_of_payment }}</span></div>
      {% if pe.reference_no and not pe.reference_no.startswith(pe.mode_of_payment or "") %}<div class="rc-kv"><span>Reference</span><span>{{ pe.reference_no }}</span></div>{% endif %}{% endif %}
    </div>
  </div>

  <table class="rc-t">
    <thead><tr><th>#</th><th>Particulars</th><th class="n">Amount (₹)</th></tr></thead>
    <tbody>
    {% for it in doc.items %}
      <tr><td>{{ loop.index }}</td><td>{{ it.item_name }}{% if doc.remarks %}<div style="color:#555;font-size:11px">{{ doc.remarks }}</div>{% endif %}</td>
      <td class="n">{{ frappe.utils.fmt_money(it.amount, currency=doc.currency) }}</td></tr>
    {% endfor %}
    </tbody>
  </table>

  <div class="rc-amt"><table>
    {% if doc.discount_amount %}<tr><td>Discount</td><td class="n">- {{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}</td></tr>{% endif %}
    {% for t in doc.taxes %}{% if t.tax_amount %}<tr><td>{{ t.description }}</td><td class="n">{{ frappe.utils.fmt_money(t.tax_amount, currency=doc.currency) }}</td></tr>{% endif %}{% endfor %}
    <tr class="g"><td>Amount Received</td><td class="n">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td></tr>
  </table></div>
  <div class="rc-words">Rupees {{ frappe.utils.money_in_words(doc.grand_total, doc.currency).replace("INR", "").replace("only.", "only") }}</div>

  {% if so %}
  <div class="rc-bal">
    <span>Total fee {{ frappe.utils.fmt_money(so.grand_total, currency=doc.currency) }} · Paid so far <b class="green">{{ frappe.utils.fmt_money(paid_total, currency=doc.currency) }}</b></span>
    <span>Balance pending <b class="{{ 'green' if pending_total <= 0.5 else 'red' }}">{{ frappe.utils.fmt_money(pending_total, currency=doc.currency) }}</b></span>
  </div>
  {% endif %}

  <div class="rc-foot">
    <div>Received by: {{ frappe.db.get_value("User", doc.owner, "full_name") or doc.owner }}</div>
    <div class="rc-sign">Authorised Signatory<br>{{ company.company_name }}</div>
  </div>
  <div class="rc-note">This is a computer-generated receipt. Fees once paid are subject to the institute's refund policy.</div>
</div>
